// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount, uint256 ndeposits, address depositor) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(depositor != address(0));
        vm.assume(amount > 0);
        uint256 n = bound(ndeposits, 1, 10);
        for (uint256 i = 0; i < n; i++) {
            vm.deal(depositor, amount);
            vm.prank(depositor);
            (bool ok,) = address(c).call{value: amount}("");
            assertTrue(ok);
        }
        // General rule: each accepted deposit increments depositsCount by exactly one,
        // so after n deposits the counter equals n.
        assertEq(c.depositsCount(), n);
    }
}
